pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(this);

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address recipient, uint256 depositAmount) public {
        // Ensure depositAmount is reasonable
        vm.assume(depositAmount > 0 && depositAmount < 1e30);
        // Fund the contract
        vm.deal(address(c), depositAmount);
        // Call withdrawAll as owner
