pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address payable recipient, uint256 initialBalance) public {
        vm.assume(recipient != address(0) && recipient != address(c));
        initialBalance = bound(initialBalance, 1, 1e30);
        vm.deal(address(c), initialBalance);
        uint256 balanceBefore = address(c).balance;
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted && address(c).balance == 0 || reverted && address(c).balance == balanceBefore);
    }
}

