        // The general rule: after a successful withdrawAll, the contract balance is zero
        assertTrue(address(c).balance == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, address recipient) public {
        vm.assume(caller != address(this) && caller != address(0) && recipient != address(0));
        vm.deal(address(c), 1 ether);
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));
        if (caller == address(this)) {
            assertTrue(success);
            assertEq(address(c).balance, 0);
        } else {
            assertTrue(!success);
        }
    }
}
